import{_ as l,a0 as d,w as o,s as u,I as t,x as a,a1 as i,A as p,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Ubuntu 中使用 apt 命令列出可升級的軟件包 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中使用 apt 命令列出可升級的軟件包 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中使用 apt 命令列出可升級的軟件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中使用 apt 命令列出可升級的軟件包 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220712 List Upgradable Packages With apt Command in Ubuntu","title":"在 Ubuntu 中使用 apt 命令列出可升級的軟件包","tag":"202207","desc":""},"relativePath":"202207/20220712 List Upgradable Packages With apt Command in Ubuntu.md","filePath":"[post].md"}'),r={name:"202207/20220712 List Upgradable Packages With apt Command in Ubuntu.md"};function g(b,s,h,k,m,f){const e=d("Link");return o(),u("div",null,[s[36]||(s[36]=t("h1",{id:"在-ubuntu-中使用-apt-命令列出可升級的軟件包",tabindex:"-1"},[a("在 Ubuntu 中使用 apt 命令列出可升級的軟件包 "),t("a",{class:"header-anchor",href:"#在-ubuntu-中使用-apt-命令列出可升級的軟件包","aria-label":"Permalink to “在 Ubuntu 中使用 apt 命令列出可升級的軟件包”"},"​")],-1)),s[37]||(s[37]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/24/230954qjko0c0sn55ohjf0.jpg",alt:""})],-1)),t("p",null,[i(e,{href:"https://itsfoss.com/apt-command-guide/"},{default:p(()=>[...s[0]||(s[0]=[a("apt 命令",-1)])]),_:1}),s[1]||(s[1]=a(" 用於 Debian 和 Ubuntu 中的包管理。雖然你可能已經熟悉安裝和刪除選項，但 ",-1)),s[2]||(s[2]=t("code",null,"apt",-1)),s[3]||(s[3]=a(" 還提供了一些額外的功能。",-1))]),s[38]||(s[38]=n(`<p>其中之一是能夠查看系統上所有可升級的軟件包。要顯示它們，你所要做的就是在終端中使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --upgradable</span></span></code></pre></div><p>如你所見，你甚至不需要使用 <code>sudo</code> 來列出可更新的包。它只是列出了可以更新的包，而不會更新它們。</p><p>實際上，當你運行 <code>sudo apt update</code> 命令更新本地包倉庫緩存時，<code>apt</code> 命令會添加此提示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fetched 1,243 kB in 17s (71.4 kB/s)           </span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>Building dependency tree... Done</span></span>
<span class="line"><span>Reading state information... Done</span></span>
<span class="line"><span>30 packages can be upgraded. Run &#39;apt list --upgradable&#39; to see them.</span></span></code></pre></div><p>我不記得在舊的 <code>apt-get</code> 命令中有任何類似的直接選項來列出所有可升級的包。這是 <code>apt</code> 在舊的 <code>apt-get</code> 命令之上添加的幾個新功能之一。</p><p>讓我們更詳細地討論一下。</p><h3 id="列出所有可升級的包" tabindex="-1">列出所有可升級的包 <a class="header-anchor" href="#列出所有可升級的包" aria-label="Permalink to “列出所有可升級的包”">​</a></h3>`,8)),t("p",null,[s[5]||(s[5]=a("你在這裏應該知道的是",-1)),s[6]||(s[6]=t("strong",null,"你只能列出通過 APT 包管理器可用的更新",-1)),s[7]||(s[7]=a("。因此，如果你已將 PPA 或 ",-1)),i(e,{href:"https://itsfoss.com/adding-external-repositories-ubuntu/"},{default:p(()=>[...s[4]||(s[4]=[a("外部倉庫",-1)])]),_:1}),s[8]||(s[8]=a(" 添加到系統的 ",-1)),s[9]||(s[9]=t("code",null,"sources.list",-1)),s[10]||(s[10]=a("，你也將看到來自它們的更新。",-1))]),s[39]||(s[39]=n(`<p>但是你不會在這裏獲得 AppImage、Flatpak、Snap 或一些其他打包格式的更新。</p><p>換句話説，它只適用於 APT 包。</p><p>因此，要列出 Ubuntu 或 Debian 系統上的所有可升級包，你應該首先更新本地包緩存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>然後你的系統將知道可用的軟件包更新。<code>apt</code> 命令告訴你在 update 命令結束時可以升級多少個軟件包：</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/update-package-cache-ubuntu.png" alt="The apt command shows the number of upgradable packages at the bottom of the apt update command output"></p><p>要查看可以升級的軟件包，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt list --upgradable</span></span></code></pre></div><p>你應該看到這樣的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~$ apt list --upgradable </span></span>
<span class="line"><span>Listing... Done</span></span>
<span class="line"><span>apparmor/jammy-updates 3.0.4-2ubuntu2.1 amd64 [upgradable from: 3.0.4-2ubuntu2]</span></span>
<span class="line"><span>brave-browser/stable 1.40.113 amd64 [upgradable from: 1.40.107]</span></span>
<span class="line"><span>evolution-data-server-common/jammy-updates,jammy-updates 3.44.2-0ubuntu1 all [upgradable from: 3.44.1-0ubuntu2]</span></span>
<span class="line"><span>evolution-data-server/jammy-updates 3.44.2-0ubuntu1 amd64 [upgradable from: 3.44.1-0ubuntu2]</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/apt-list-upgradable-packages-ubuntu.webp" alt="Listing all the upgradable packages"></p><p>它<strong>按字母順序列出所有可升級的軟件包</strong>以及有關當前安裝版本和新可用軟件包版本的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>brave-browser/stable 1.40.113 amd64 [upgradable from: 1.40.107]</span></span></code></pre></div><p>例如，這顯示我係統上安裝了 Brave 瀏覽器，版本 1.40.107，並且版本 1.40.113 可用。</p><p>你能用這些信息做什麼？讓我分享一些我能想到的事情。</p><h3 id="升級所有包" tabindex="-1">升級所有包 <a class="header-anchor" href="#升級所有包" aria-label="Permalink to “升級所有包”">​</a></h3><p>這可能是大多數普通 Ubuntu 用户所做的。你可以使用以下命令升級所有可升級包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>它列出了將要升級的軟件包，然後要求按回車或 <code>Y</code> 確認升級。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/upgrade-all-packages-ubuntu.webp" alt="Upgrade all packages"></p><p>如果你確定要升級所有軟件包，則可以通過在命令中添加 <code>-y</code> 來跳過 “Do you want to continue” 部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade -y</span></span></code></pre></div><h3 id="模擬升級-但不升級任何包" tabindex="-1">模擬升級（但不升級任何包） <a class="header-anchor" href="#模擬升級-但不升級任何包" aria-label="Permalink to “模擬升級（但不升級任何包）”">​</a></h3><p>這是人們在 <code>apt list</code> 命令之前所做的。使用模擬選項，你實際上不會進行任何更改。它僅顯示運行升級時將安裝或升級的軟件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt -s upgrade</span></span></code></pre></div><p>你不需要使用 <code>sudo</code>（即使我在下面的截圖中使用了它）。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/07/run-an-upgrade-simulation-apt-ubuntu.webp" alt="Running an upgrade simulation with apt command"></p><h3 id="僅升級選定的包" tabindex="-1">僅升級選定的包 <a class="header-anchor" href="#僅升級選定的包" aria-label="Permalink to “僅升級選定的包”">​</a></h3><p>如果你正在管理一個 Ubuntu 服務器，並且你不想升級所有軟件包，而只想升級少數選定的軟件包中的一個（如 MySQL/Ngnix），你可以使用 <code>apt</code> 命令輕鬆完成。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt --only-upgrade install package_name</span></span></code></pre></div><p>實際上，如果你在已安裝且有可用更新的軟件包上運行 <code>apt install</code> 命令，它將升級該軟件包。</p><p>使用 <code>--only-upgrade</code> 標誌，你可以確保<strong>僅升級</strong>軟件包（如果已安裝）。如果尚未安裝，它將不會安裝給定的包。</p><p>你還可以通過提供名稱來升級選定的幾個包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt --only-upgrade install package1 package2</span></span></code></pre></div>`,34)),t("p",null,[s[12]||(s[12]=a("你也可以做相反的事情，",-1)),i(e,{href:"https://itsfoss.com/prevent-package-update-ubuntu/"},{default:p(()=>[...s[11]||(s[11]=[a("升級時保留選定的軟件包",-1)])]),_:1}),s[13]||(s[13]=a("。",-1))]),s[40]||(s[40]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark hold package_name</span></span></code></pre></div><p>這樣，當你升級所有系統包時，將不會升級給定的包。</p><p>你可以使用以下命令刪除保留設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-mark unhold package_name</span></span></code></pre></div><h3 id="是否顯示內核升級" tabindex="-1">是否顯示內核升級？ <a class="header-anchor" href="#是否顯示內核升級" aria-label="Permalink to “是否顯示內核升級？”">​</a></h3><p>這有點棘手。</p><p>當你運行 <code>apt list –upgradable</code> 命令時，它會顯示所有可以升級的包。</p><p>但是如果有新的內核版本可用，它們可能不會顯示，因為內核包名稱以 <code>linux-headers-x-y</code> 開頭。這是因為系統將它們視為新包，而不是對已安裝的包 <code>linux-headers-a-b</code> 的升級。</p><p>但是，你仍然會在可升級包列表中看到 <code>linux-generic-hwe</code> 類型的包，因為該軟件包將被升級（使用較新的內核）。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>',10)),t("p",null,[s[15]||(s[15]=a("列出可升級包的能力是 ",-1)),s[16]||(s[16]=t("code",null,"apt",-1)),s[17]||(s[17]=a(" 命令為舊的 ",-1)),s[18]||(s[18]=t("code",null,"apt-get",-1)),s[19]||(s[19]=a(" 命令帶來的幾個新功能之一。有關此主題的更多信息，你可以閲讀我 ",-1)),i(e,{href:"https://itsfoss.com/apt-vs-apt-get-difference/"},{default:p(()=>[...s[14]||(s[14]=[a("解釋 apt 和 apt-get 命令之間的區別",-1)])]),_:1}),s[20]||(s[20]=a(" 的文章。",-1))]),s[41]||(s[41]=t("p",null,"作為桌面用户，我並不總是檢查可以升級的軟件包。我直接去升級。但是，當我管理服務器時，我更喜歡查看可用的更新，然後決定是否進行升級。",-1)),s[42]||(s[42]=t("p",null,"你呢？你覺得這個功能對你自己有用嗎？",-1)),s[43]||(s[43]=t("hr",null,null,-1)),t("p",null,[s[22]||(s[22]=a("via: ",-1)),i(e,{href:"https://itsfoss.com/apt-list-upgradable/"},{default:p(()=>[...s[21]||(s[21]=[a("https://itsfoss.com/apt-list-upgradable/",-1)])]),_:1})]),t("p",null,[s[27]||(s[27]=a("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:p(()=>[...s[23]||(s[23]=[a("Abhishek Prakash",-1)])]),_:1}),s[28]||(s[28]=a(" 選題：",-1)),i(e,{href:"https://github.com/lkxed"},{default:p(()=>[...s[24]||(s[24]=[a("lkxed",-1)])]),_:1}),s[29]||(s[29]=a(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[25]||(s[25]=[a("geekpi",-1)])]),_:1}),s[30]||(s[30]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[26]||(s[26]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[33]||(s[33]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[31]||(s[31]=[a("LCTT",-1)])]),_:1}),s[34]||(s[34]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[32]||(s[32]=[a("Linux中國",-1)])]),_:1}),s[35]||(s[35]=a(" 榮譽推出",-1))])])}const x=l(r,[["render",g]]);export{C as __pageData,x as default};
